def minimax(nums, memo):
    nums = tuple(sorted(nums))
    if nums in memo:
        return memo[nums]

    s = sum(nums)
    for x in nums:
        if x > s - x:
            return len(nums)
    if all(x == 0 for x in nums):
        return len(nums)

    n = len(nums)
    results_for_A = []
    for i in range(n):
        for j in range(i + 1, n):
            x, y = nums[i], nums[j]

            # B's option 1: x+y
            new_nums_1 = list(nums)
            new_nums_1.pop(j)
            new_nums_1.pop(i)
            new_nums_1.append(x + y)
            res1 = minimax(tuple(new_nums_1), memo)

            # B's option 2: |x-y|
            new_nums_2 = list(nums)
            new_nums_2.pop(j)
            new_nums_2.pop(i)
            new_nums_2.append(abs(x - y))
            res2 = minimax(tuple(new_nums_2), memo)

            results_for_A.append(min(res1, res2))

    res = max(results_for_A)
    memo[nums] = res
    return res

def get_popcount(n):
    return bin(n).count('1')

# We'll test the popcount hypothesis for larger n
# But minimax is too slow for large n.
# Let's see how far we can go.
for n in range(1, 21):
    print(f"N={n}: {minimax([1]*n, {})} (Popcount: {get_popcount(n)})")
